CREATE TABLE IF NOT EXISTS src_erp.erp_mrp_run(id BIGINT AUTO_INCREMENT PRIMARY KEY,run_no VARCHAR(32) NOT NULL UNIQUE,run_type VARCHAR(16) NOT NULL,sales_order_no VARCHAR(32),factory_code VARCHAR(32),plan_date DATE NOT NULL,status VARCHAR(16) DEFAULT 'CREATED',started_at DATETIME(3),finished_at DATETIME(3),created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS src_erp.erp_mrp_requirement(id BIGINT AUTO_INCREMENT PRIMARY KEY,run_id BIGINT NOT NULL,parent_material_code VARCHAR(32),material_code VARCHAR(32) NOT NULL,material_type VARCHAR(16),level_no INT DEFAULT 0,gross_requirement DECIMAL(18,4) NOT NULL,available_qty DECIMAL(18,4) DEFAULT 0,incoming_qty DECIMAL(18,4) DEFAULT 0,safety_stock DECIMAL(18,4) DEFAULT 0,net_requirement DECIMAL(18,4) NOT NULL,required_date DATE,shortage_flag TINYINT(1) DEFAULT 0,KEY idx_requirement_run(run_id));
CREATE TABLE IF NOT EXISTS src_erp.erp_plan_suggestion(id BIGINT AUTO_INCREMENT PRIMARY KEY,run_id BIGINT NOT NULL,suggestion_no VARCHAR(32) NOT NULL UNIQUE,suggestion_type VARCHAR(16) NOT NULL,material_code VARCHAR(32) NOT NULL,quantity DECIMAL(18,4) NOT NULL,unit_code VARCHAR(16),required_date DATE,source_sales_order_no VARCHAR(32),status VARCHAR(16) DEFAULT 'PROPOSED',converted_order_no VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),KEY idx_suggestion_run(run_id));
CREATE TABLE IF NOT EXISTS src_erp.erp_purchase_requisition(id BIGINT AUTO_INCREMENT PRIMARY KEY,requisition_no VARCHAR(32) NOT NULL UNIQUE,source_suggestion_no VARCHAR(32) NOT NULL,material_code VARCHAR(32) NOT NULL,quantity DECIMAL(18,4) NOT NULL,required_date DATE,status VARCHAR(16) DEFAULT 'CREATED',created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
